import java.io.*;
import java.util.*;

public class E {
    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String readToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int readInt() {
            return Integer.parseInt(readToken());
        }

        long readLong() {
            return Long.parseLong(readToken());
        }

        String readLine() {
            String line = "";
            try {
                line = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return line;
        }
    }

    static InputReader in = new InputReader();
    static PrintWriter outStream = new PrintWriter(System.out);

    private static int[] getIntArray(int size) {
        int[] array = new int[size];
        for (int i = 0; i < size; i++) {
            array[i] = in.readInt();
        }
        return array;
    }

    private static long[] getLongArray(int size) {
        long[] array = new long[size];
        for (int i = 0; i < size; i++) {
            array[i] = in.readLong();
        }
        return array;
    }

    private static int readInt() {
        return in.readInt();
    }

    private static long readLong() {
        return in.readLong();
    }

    private static String readString() {
        return in.readToken();
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    static int binarySearch(List<Long> list, long val, int start) {
        int left = start, right = list.size() - 1;
        int res = list.size();

        while (left <= right) {
            int mid = (left + right) / 2;
            if (list.get(mid) > val) {
                if (mid == 0) return mid;
                if (list.get(mid - 1) <= val) return mid;
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return res;
    }

    static long process(List<Node> nodes, long[] b, int index) {
        if (index == 3) return 0;

        Node node = nodes.get(index);
        int bIdx = node.ind - 1;
        if (bIdx == -1) bIdx = 2;

        long minA = Math.min(node.val, b[bIdx]);
        node.val -= minA;
        b[bIdx] -= minA;

        long minB = Math.min(node.val, b[node.ind]);
        node.val -= minB;
        b[node.ind] -= minB;

        long resA = node.val + process(nodes, b, index + 1);
        node.val += minA + minB;
        b[bIdx] += minA;
        b[node.ind] += minB;

        // second scenario
        node = nodes.get(index);
        bIdx = node.ind - 1;
        if (bIdx == -1) bIdx = 2;

        long minC = Math.min(node.val, b[node.ind]);
        node.val -= minC;
        b[node.ind] -= minC;

        long minD = Math.min(node.val, b[bIdx]);
        node.val -= minD;
        b[bIdx] -= minD;

        long resB = node.val + process(nodes, b, index + 1);
        node.val += minC + minD;
        b[bIdx] += minD;
        b[node.ind] += minC;

        return Math.min(resA, resB);
    }

    public static void main(String[] args) {
        StringBuilder output = new StringBuilder();
        int t = 1;
        while (t-- > 0) {
            int n = readInt();
            long[] a = getLongArray(3);
            long[] b = getLongArray(3);

            long maxVal = Math.min(a[0], b[1]) + Math.min(a[1], b[2]) + Math.min(a[2], b[0]);
            long minVal = Math.max(0, a[0] + b[1] - n) + Math.max(0, a[1] + b[2] - n) + Math.max(0, a[2] + b[0] - n);
            output.append(minVal).append(" ").append(maxVal).append("\n");
        }
        outStream.print(output.toString());
        outStream.flush();
    }

    static class Node {
        int ind;
        long val;

        public Node(int ind, long val) {
            this.ind = ind;
            this.val = val;
        }
    }
}
